import re

from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import CommandFailure


class RunDspCommand(GenericUnixCommand):
    """Run custom dsp command."""

    __error_command_not_found = re.compile(r"Command\s+not\s+found.")

    def __init__(self, connection, dsp_command, prompt=None, newline_chars=None, runner=None):
        """
        run_dsp_command command.

        :param connection: Moler connection to device, terminal when command is executed.
        :param dsp_command: custom dsp command to run.
        :param prompt: prompt (on system where command runs).
        :param newline_chars: Characters to split lines - list.
        :param runner: Runner to run command.
        """
        super(RunDspCommand, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                            runner=runner)
        self.dsp_command = dsp_command
        self.ret_required = True
        self.current_ret["LINES"] = []

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return self.dsp_command

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if self._regex_helper.search_compiled(self.__error_command_not_found, line):
            self.set_exception(CommandFailure(self, "Command not found"))
        self.current_ret["LINES"].append(line)

        return super(RunDspCommand, self).on_new_line(line, is_full_line)


